const LRC_TEMPLATE = `
    <!DOCTYPE html>
    <html lang="zh">
        <head>
            <meta charset="UTF-8">
            <title>AerMusic Lyric</title>
            <link rel="stylesheet" type="text/css" href="https://cdn.xrbk.cn/fonts/MiSans-Semibold/result.css">
            <link rel="stylesheet" href="/static/assets/app/lrc.min.css">
        </head>
        <body class="{{TRANS_CLASS}}">
            <div class="container"><ul class="data-list"></ul></div>
        </body>
        <script>
            var lrc = \`{{LYRIC_CONTENT}}\`;
            const tlyricData = {{TLYRIC_JSON}};
            const showMeta = {{SHOW_META}};
            const showContributors = {{SHOW_CONTRIBUTORS}};
            const lyricImgPool = {{LYRIC_IMG_POOL}};
            window.lyricRestoreImgTokens = function(s) {
                return String(s).replace(/\\u0001(\\d+)\\u0001/g, (m, i) => lyricImgPool[Number(i)] || "");
            };
        <\/script>
        <script type="module" src="/static/assets/app/lrc.min.js"><\/script>
    </html>
`

const KRC_TEMPLATE = `
    <!DOCTYPE html>
    <html lang="zh">
        <head>
            <meta charset="UTF-8">
            <title>AerMusic KRC Lyric</title>
            <link rel="stylesheet" type="text/css" href="https://cdn.xrbk.cn/fonts/MiSans-Semibold/result.css">
            <link rel="stylesheet" href="/static/assets/app/krc.min.css">
        </head>
        <body class="{{TRANS_CLASS}}">
            <div class="container"><ul class="data-list"></ul></div>
        </body>
        <script>
            const krcData = {{KRC_JSON}};
            const tlyricData = {{TLYRIC_JSON}};
            const showMeta = {{SHOW_META}};
            const showContributors = {{SHOW_CONTRIBUTORS}};
            const lyricImgPool = {{LYRIC_IMG_POOL}};
            window.lyricRestoreImgTokens = function(s) {
                return String(s).replace(/\\u0001(\\d+)\\u0001/g, (m, i) => lyricImgPool[Number(i)] || "");
            };
        <\/script>
        <script type="module" src="/static/assets/app/krc.min.js"><\/script>
    </html>
`

/* 歌词文本以 HTML 形式渲染, 这里统一转义; 封面图走令牌池白名单, 其余标签一律转义 */
function escHtml(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }
window.lyricEsc = escHtml;
const LYRIC_IMG_TOKEN = "\u0001";
window.__lyricImgPool = [];
window.safeTemplateReplace = function(tpl, token, value) {
    let text = String(tpl).split(token).join(value);
    if (text.includes("{{LYRIC_IMG_POOL}}")) {
        const pool = window.__lyricImgPool || [];
        text = text.split("{{LYRIC_IMG_POOL}}").join(window.escapeScriptJson(JSON.stringify(pool)));
    }
    return text;
};
window.escapeScriptEmbed = function(s) {
    return String(s).replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${").replace(/<\//g, "<\\/");
};
window.escapeScriptJson = function(s) { return String(s).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029"); };

function lyricImgToken(picUrl) {
    if (!picUrl || !/^https?:\/\//i.test(picUrl)) return "";
    const img = '<img src="' + escHtml(picUrl) + '?param=50y50" class="lyric-img">';
    window.__lyricImgPool.push(img);
    return LYRIC_IMG_TOKEN + (window.__lyricImgPool.length - 1) + LYRIC_IMG_TOKEN;
}

const isContributorText = (text) => /^(?:滚动歌词贡献者|翻译歌词贡献者)\s*[:：]/.test(String(text || "").replace(/\u0001\d+\u0001/g, "").trim());
window.lyricStripImgTokens = function(s) { return String(s).replace(/\u0001\d+\u0001/g, ""); };
window.lyricRestoreImgTokens = function(s) {
    return String(s).replace(/\u0001(\d+)\u0001/g, (m, i) => window.__lyricImgPool[Number(i)] || "");
};

function lyrictolyric(args) {
    window.__lyricImgPool.length = 0;
    const input = args.lyricinput; const output = args.lyricoutput; const content = String(args.content || "").trim();
    if (input === output) return content;
    try {
        if (input === "packlrc" && output === "arc") {
            const lines = content.split("\n").filter(line => line.trim());
            let startMetas = [];
            let lyricLines = [];
            let endMetas = [];
            let hasLyricStarted = false;
            lines.forEach(line => {
                const trimLine = line.trim();
                if (trimLine.startsWith("{")) {
                    try {
                        const meta = JSON.parse(trimLine);
                        if (meta.t !== undefined && meta.c) {
                            const text = meta.c.reduce((acc, item) => {
                                return acc + lyricImgToken(item.li) + (item.tx || "");
                            }, "");
                            const lineItem = { time: meta.t, text: text, isMeta: true, isContributor: isContributorText(text) };
                            if (!hasLyricStarted) {
                                startMetas.push(lineItem);
                            } else {
                                endMetas.push(lineItem);
                            }
                        }
                    } catch (e) {}
                } 
                else {
                    const timeReg = /\[(\d+):(\d+)[.:](\d{1,3})\](.*)/;
                    const timeMatch = trimLine.match(timeReg);
                    if (timeMatch) {
                        hasLyricStarted = true;
                        const m = parseInt(timeMatch[1]);
                        const s = parseInt(timeMatch[2]);
                        const ms = parseInt(timeMatch[3].padEnd(3, "0"));
                        const timeMs = m * 60000 + s * 1000 + ms;
                        const text = timeMatch[4].trim();
                        lyricLines.push({ time: timeMs, text: text, isMeta: false });
                    }
                }
            });
        
            lyricLines.sort((a, b) => a.time - b.time);
            const firstTime = lyricLines.length ? lyricLines[0].time : 8000;
            startMetas.forEach((meta, idx) => {
                meta.time = Math.floor(firstTime / (startMetas.length + 1) * idx);
            });
            const lastTime = lyricLines.length ? lyricLines[lyricLines.length - 1].time : 0;
            endMetas.forEach((meta, idx) => {
                meta.time = lastTime + 300 * (idx + 1);
            });
            const allLines = [...startMetas, ...lyricLines, ...endMetas];
            allLines.sort((a, b) => a.time - b.time);
            let reconstructedLrc = allLines.map(l => {
                const totalMs = l.time;
                const m = Math.floor(totalMs / 60000);
                const remain = totalMs % 60000;
                const s = Math.floor(remain / 1000);
                const ms = remain % 1000;
                const timeStr = `[${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}.${ms.toString().padStart(2, "0")}]`;
                if (l.isMeta) return JSON.stringify({ t: l.time, c: [{ tx: l.text }] });
                return timeStr + l.text;
            }).join("\n");
        
            return JSON.stringify({ type: "lrc", lyric: reconstructedLrc });
        }
        
        if (input === "packyrc" && output === "arc") {
            const lines = content.split("\n").filter(line => line.trim());
            let startMetas = [];
            let lyricLines = [];
            let endMetas = [];
            let hasLyricStarted = false;
            lines.forEach(line => {
                if (line.startsWith("{")) {
                    try {
                        const meta = JSON.parse(line);
                        if (meta.t !== undefined && meta.c) {
                            const text = meta.c.reduce((acc, item) => {
                                return acc + lyricImgToken(item.li) + (item.tx || "");
                            }, "");
                            if (!hasLyricStarted) {
                                startMetas.push({ text: text, isMeta: true, isContributor: isContributorText(text) });
                            } else {
                                endMetas.push({ text: text, isMeta: true, isContributor: isContributorText(text) });
                            }
                        }
                    } catch (e) {}
                } else {
                    hasLyricStarted = true;
                    const match = line.match(/^\[(\d+),(\d+)\]/);
                    if (match) {
                        const wordMatches = [...line.matchAll(/\((\d+),(\d+),\d+\)([^\(]+)/g)];
                        const words = wordMatches.map(m => ({ text: m[3], o: parseInt(m[1]), d: parseInt(m[2]) }));
                        if (words.length) lyricLines.push({ time: parseInt(match[1]), words: words, isMeta: false, duration: parseInt(match[2]) });
                    }
                }
            });
            lyricLines.sort((a, b) => a.time - b.time);
            const firstTime = lyricLines.length > 0 ? lyricLines[0].time : 8000;
            if (startMetas.length > 0) {
                startMetas.forEach((meta, idx) => {
                    meta.time = Math.floor(firstTime / startMetas.length * idx);
                });
            }
            let lastTime = lyricLines.length > 0 ? lyricLines[lyricLines.length - 1].time : 0;
            let dura = lyricLines.length > 0 ? lyricLines[lyricLines.length - 1].duration : 0;
            endMetas.forEach((meta, idx) => {
                meta.time = lastTime + dura + 300 * (idx + 1);
            });
            const allLines = [...startMetas, ...lyricLines, ...endMetas];
            allLines.sort((a, b) => a.time - b.time);
            const result = { type: "krc", lyric: {} };
            allLines.forEach((line, i) => {
                if (line.isMeta) {
                    result.lyric[i + 1] = { words: [{ text: line.text, o: line.time, d: 1 }], isMeta: true, isContributor: line.isContributor || false };
                } else {
                    result.lyric[i + 1] = { words: line.words, isMeta: false, isContributor: false };
                }
            });
            return JSON.stringify(result);
        }
    } catch (e) { return content; }
    return content;
}
